import 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport '../../../core/providers/core_providers.dart';\nimport '../providers/homework_providers.dart';\nimport 'subject_details_screen.dart';\n\nclass SubjectsTab extends ConsumerWidget {\n  const SubjectsTab({Key? key}) : super(key: key);\n\n  @override\n  Widget build(BuildContext context, WidgetRef ref) {\n    final localStorage = ref.watch(localStorageServiceProvider);\n    final gradeId = localStorage.getSelectedGrade();\n\n    if (gradeId == null) {\n      return const Center(child: Text('لم يتم تحديد الصف'));\n    }\n\n    final subjectsAsync = ref.watch(subjectsProvider(gradeId));\n\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('المواد الدراسية'),\n        centerTitle: true,\n      ),\n      body: subjectsAsync.when(\n        data: (subjects) {\n          if (subjects.isEmpty) {\n            return const Center(child: Text('لا توجد مواد مضافة لهذا الصف'));\n          }\n          return GridView.builder(\n            padding: const EdgeInsets.all(16),\n            gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(\n              crossAxisCount: 2,\n              crossAxisSpacing: 16,\n              mainAxisSpacing: 16,\n              childAspectRatio: 1,\n            ),\n            itemCount: subjects.length,\n            itemBuilder: (context, index) {\n              final subject = subjects[index];\n              return InkWell(\n                onTap: () {\n                  Navigator.push(\n                    context,\n                    MaterialPageRoute(\n                      builder: (_) => SubjectDetailsScreen(subject: subject),\n                    ),\n                  );\n                },\n                child: Card(\n                  elevation: 3,\n                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),\n                  child: Column(\n                    mainAxisAlignment: MainAxisAlignment.center,\n                    children: [\n                      // We can use an icon or an image if `subject.icon` is a url\n                      Icon(Icons.book, size: 50, color: Colors.blue[700]),\n                      const SizedBox(height: 16),\n                      Text(\n                        subject.name,\n                        style: const TextStyle(fontSize: 18, fontWeight: FontWeight.bold),\n                        textAlign: TextAlign.center,\n                      ),\n                    ],\n                  ),\n                ),\n              );\n            },\n          );\n        },\n        loading: () => const Center(child: CircularProgressIndicator()),\n        error: (err, stack) => Center(child: Text('خطأ: $err')),\n      ),\n    );\n  }\n}\n